public class StdTypeResolverBuilder_typeProperty_TriageGen0Test {

    @Test
    public void testTypeProperty_WithValidString() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        String expectedProp = "myCustomProperty";

        StdTypeResolverBuilder result = builder.typeProperty(expectedProp);

        assertEquals("Should return the same builder instance (fluent API)", builder, result);
        assertEquals("Property name should be set to the provided string", expectedProp, builder.getTypeProperty());
    }

