    @Test
    public void testTypeProperty_WithEmptyString() {
        TypeIdResolver idResolver = mock(TypeIdResolver.class);
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        builder.init(JsonTypeInfo.Id.NAME, idResolver);

        // Manually simulate the default property name via the idType if possible, 
        // but since we use NAME, it will use the internal logic.
        builder.typeProperty("");

        assertNotNull("Property should be set to default when empty string is passed", builder.getTypeProperty());
    }

    @Test
    public void testTypeProperty_WithWhitespaceString() {
        // Testing that a string with only spaces is NOT treated as empty/null 
        // (based on the code: length == 0)
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        builder.init(JsonTypeInfo.Id.NAME, mock(TypeIdResolver.class));

        String whitespaceProp = "   ";
        builder.typeProperty(whitespaceProp);

        assertEquals("Whitespace string should be treated as a valid property name", whitespaceProp, builder.getTypeProperty());
    }
